# Sphinx configuration for the PCMS documentation.
#
# Build from the repository root with:
#   pip install -r docs/requirements.txt
#   sphinx-build -b html docs docs/_build/html
#
# The C++ API is generated by Doxygen (XML only) and rendered with
# Breathe/Exhale. The Python API is rendered with autodoc from the compiled
# ``pcms`` module, which must be importable (e.g. on PYTHONPATH).

import pathlib
import subprocess

from sphinx.util import logging

logger = logging.getLogger(__name__)

docs_dir = pathlib.Path(__file__).parent.resolve()
repo_root = docs_dir.parent

project = "PCMS"
author = "SCOREC"
copyright = "Rensselaer Polytechnic Institute"

extensions = [
    "breathe",
    "exhale",
    "myst_parser",
    "sphinx.ext.autodoc",
    "sphinx.ext.mathjax",
]

source_suffix = {".rst": "restructuredtext", ".md": "markdown"}
exclude_patterns = ["_build", "_doxygen"]

html_theme = "sphinx_rtd_theme"

# -- C++ API -----------------------------------------------------------------

# The Doxyfile at the repository root writes XML to docs/_doxygen/xml.
subprocess.run(["doxygen", "Doxyfile"], cwd=repo_root, check=True)

breathe_projects = {"pcms": str(docs_dir / "_doxygen" / "xml")}
breathe_default_project = "pcms"
breathe_default_members = ("members", "undoc-members")

exhale_args = {
    "containmentFolder": "./api",
    "rootFileName": "library_root.rst",
    "rootFileTitle": "C++ API",
    "doxygenStripFromPath": str(repo_root),
    "createTreeView": True,
    "exhaleExecutesDoxygen": False,
}

primary_domain = "cpp"

# The C API declares its handles as `typedef struct X X;`, which the C++
# domain reports as duplicate declarations.
suppress_warnings = ["duplicate_declaration.cpp"]

# -- Python API --------------------------------------------------------------

try:
    import pcms  # noqa: F401

    tags.add("pcms_python")  # noqa: F821 (provided by Sphinx)
except ImportError:
    logger.warning(
        "the pcms Python module is not importable; the Python API page will "
        "be empty. Build PCMS with -DPCMS_ENABLE_Python=ON and add it to "
        "PYTHONPATH."
    )
    autodoc_mock_imports = ["pcms"]
